#!/usr/bin/env node
//
// Builds the four downloadable assets in public/downloads/.
//
// Run with:  npx --yes -p docx@9 -p exceljs@4 -p pdfkit@0.15 node scripts/build-downloads.mjs
//
// The libraries are deliberately NOT in package.json. These are static
// artifacts committed to the repo and regenerated by hand when the content
// changes; adding three document libraries to a marketing site's runtime to
// produce four files that never change at request time would be the wrong
// trade.
//
// Why these exist: two pages promise a file in their title —
// how-to-write-av-rfp says "(Free Template)" and event-budget-template-free-2026
// says "Free Download" — and neither had one. A visitor arriving from search
// for a template and finding an essay leaves.

import { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell, WidthType, BorderStyle } from 'docx'
import ExcelJS from 'exceljs'
import PDFDocument from 'pdfkit'
import { writeFileSync, createWriteStream } from 'node:fs'

const DARK = '08172E'
const GREEN = '10B981'
const GREY = '6B7280'
const OUT = 'public/downloads'

const p = (text, opts = {}) => new Paragraph({
  spacing: { after: opts.after ?? 120 },
  alignment: opts.align,
  children: [new TextRun({ text, bold: opts.bold, italics: opts.italic, size: opts.size ?? 22, color: opts.color ?? '1F2937' })],
})
const h = (text, level = HeadingLevel.HEADING_2) => new Paragraph({
  heading: level, spacing: { before: 280, after: 140 },
  children: [new TextRun({ text, bold: true, color: DARK, size: level === HeadingLevel.HEADING_1 ? 36 : 26 })],
})
const fill = (label) => new Paragraph({
  spacing: { after: 100 },
  children: [new TextRun({ text: label, size: 22, color: GREY })],
})
const footer = () => [
  new Paragraph({ spacing: { before: 400 }, border: { top: { style: BorderStyle.SINGLE, size: 6, color: 'E5E7EB' } }, children: [] }),
  p('Built by CueQuote — AV proposals in minutes. cuequote.com', { size: 18, color: GREY }),
]

// ── 1. AV proposal template ────────────────────────────────────────────────
async function proposalTemplate() {
  const doc = new Document({ sections: [{ children: [
    h('AV Proposal Template', HeadingLevel.HEADING_1),
    p('Replace everything in [square brackets]. Delete any row or section that does not apply. The structure is the part that does the work — keep it.', { italic: true, color: GREY }),

    h('1. Cover'),
    fill('[Your company name and logo]'),
    fill('Proposal for: [Client company]      Contact: [Name, role]'),
    fill('Event: [Event name]      Venue: [Venue, city]      Date: [Event date]'),
    fill('Prepared by: [Your name]      Issued: [date]      Valid until: [date, 14–30 days out]'),
    fill('Proposal number: [PRO-0001]'),

    h('2. Scope summary'),
    p('Two to four sentences in plain language. No equipment names — this is the section a finance director reads.', { italic: true, color: GREY }),
    fill('[Client] is running [event type] for [N] guests at [venue] on [date]. We are providing [audio / video / lighting / staging] across [N] rooms, with load-in on [date] and strike on [date]. The room seats [N] in [layout] and the main presentation is [describe]. Our crew of [N] covers setup, show operation and derig.'),

    h('3. Equipment list'),
    p('Grouped by department, quantity first, subtotal per group. A client who cannot find a line will ask about all of them.', { italic: true, color: GREY }),
    ...['AUDIO', 'VIDEO', 'LIGHTING', 'STAGING', 'CREW', 'LOGISTICS'].flatMap((cat) => ([
      new Paragraph({ spacing: { before: 160, after: 60 }, children: [new TextRun({ text: cat, bold: true, size: 22, color: DARK })] }),
      fill('[Qty] × [Item]  —  [unit price]  —  [line total]'),
      fill('[Qty] × [Item]  —  [unit price]  —  [line total]'),
      new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: 'Subtotal: [amount]', bold: true, size: 22, color: GREEN })] }),
    ])),

    h('4. Pricing'),
    new Table({
      width: { size: 100, type: WidthType.PERCENTAGE },
      rows: [
        ['Subtotal', '[amount]'], ['Discount', '[amount or —]'], ['Net', '[amount]'],
        ['VAT at [rate]', '[amount]'], ['Total', '[amount]'],
      ].map(([a, b], i) => new TableRow({ children: [
        new TableCell({ children: [p(a, { bold: i === 4 })] }),
        new TableCell({ children: [p(b, { bold: i === 4 })] }),
      ]})),
    }),
    p('Optional items, priced separately and NOT included in the total:', { bold: true }),
    fill('[Item] — [amount]        [Item] — [amount]'),
    p('Keep optional items outside the total. A client who reads one number and is invoiced another does not book you twice.', { italic: true, color: GREY }),

    h('5. Terms'),
    p('Included', { bold: true }),
    fill('[Delivery, setup, operation, derig, insurance, what else]'),
    p('Not included', { bold: true }),
    fill('[Power supply, venue fees, rigging permits, overtime beyond N hours, anything you would otherwise be argued into on site]'),
    p('Every line in the exclusions list is an argument you will not have. It is the section that pays for itself.', { italic: true, color: GREY }),
    p('Payment', { bold: true }),
    fill('[Deposit %] on acceptance, balance [N] days after the event.'),
    p('Cancellation', { bold: true }),
    fill('[Terms by notice period]'),
    p('Damage and loss', { bold: true }),
    fill('[Terms]'),

    h('6. Acceptance'),
    fill('Signature: ______________________________'),
    fill('Printed name: ___________________________'),
    fill('Position: _______________________________'),
    fill('Date: ___________________________________'),
    p('By signing, [Client] accepts the scope, pricing and terms set out above.', { italic: true }),
    ...footer(),
  ]}]})
  writeFileSync(`${OUT}/av-proposal-template.docx`, await Packer.toBuffer(doc))
}

// ── 2. AV RFP template ─────────────────────────────────────────────────────
async function rfpTemplate() {
  const doc = new Document({ sections: [{ children: [
    h('AV RFP Template', HeadingLevel.HEADING_1),
    p('Send this to AV suppliers to get quotes you can actually compare. The more of it you fill in, the less they have to assume — and assumptions are where quotes diverge.', { italic: true, color: GREY }),

    h('1. The event'),
    fill('Organisation: [name]        Contact: [name, email, phone]'),
    fill('Event name: [name]         Type: [conference / gala / launch / AGM]'),
    fill('Dates: [event date(s)]     Load-in: [date/time]     Strike: [date/time]'),
    fill('Venue: [name, address]     Room(s): [names]         Attendees: [N]'),
    fill('Seating layout: [theatre / cabaret / banquet / standing]'),

    h('2. What happens in the room'),
    p('Describe the running order, not the equipment. Suppliers price better from this than from a kit list.', { italic: true, color: GREY }),
    fill('[e.g. 09:00 registration with background music; 09:30 keynote with presenter on stage, slides and IMAG; 11:00 panel with four lapel mics; 13:00 lunch; 14:00 breakout in two rooms; 17:00 awards with walk-on music and a video package.]'),

    h('3. What you already know you need'),
    fill('Audio: [speech reinforcement / music playback / recording / hearing loop]'),
    fill('Video: [screens or LED, IMAG, presentation playback, livestream, recording]'),
    fill('Lighting: [stage wash, branding/gobo, ambient colour, house lights control]'),
    fill('Staging: [stage size and height, lectern, set, backdrop]'),
    fill('Crew: [technicians on site, show caller, rehearsal attendance]'),
    fill('Accessibility: [captioning, interpretation, hearing loop, described audio]'),

    h('4. Venue constraints'),
    p('The section suppliers most often have to guess at, and the one that moves a price most.', { italic: true, color: GREY }),
    fill('Get-in access: [loading bay / stairs / lift dimensions / distance to room]'),
    fill('Power available: [supply and location]      Rigging: [points, weight limits, permitted?]'),
    fill('House equipment usable: [what the venue already provides]'),
    fill('Noise or curfew limits: [details]           Union or venue-preferred supplier rules: [details]'),

    h('5. Budget and commercials'),
    fill('Budget range: [state one — a range gets a realistic quote, silence gets a guess]'),
    fill('Currency: [ ]        VAT: [inclusive / exclusive]'),
    fill('Payment terms you can offer: [deposit, balance timing]'),

    h('6. How to respond'),
    fill('Deadline for questions: [date]        Proposal deadline: [date]'),
    fill('Decision date: [date]                 Format: [PDF by email / portal]'),
    p('Please price each department separately with subtotals, list optional items outside the total, and state clearly what is excluded.', { bold: true }),
    p('Ask every supplier for the same structure. Three quotes in three shapes cannot be compared, which is how the cheapest-looking one wins.', { italic: true, color: GREY }),
    ...footer(),
  ]}]})
  writeFileSync(`${OUT}/av-rfp-template.docx`, await Packer.toBuffer(doc))
}

// ── 3. Event budget template ───────────────────────────────────────────────
async function budgetTemplate() {
  const wb = new ExcelJS.Workbook()
  wb.creator = 'CueQuote'
  const ws = wb.addWorksheet('Event budget')

  ws.columns = [
    { header: 'Category', key: 'cat', width: 18 },
    { header: 'Item', key: 'item', width: 40 },
    { header: 'Qty', key: 'qty', width: 8 },
    { header: 'Unit', key: 'unit', width: 12 },
    { header: 'Est. low', key: 'low', width: 12 },
    { header: 'Est. high', key: 'high', width: 12 },
    { header: 'Quoted', key: 'quoted', width: 12 },
    { header: 'Actual', key: 'actual', width: 12 },
    { header: 'Notes', key: 'notes', width: 40 },
  ]
  ws.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } }
  ws.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: `FF${DARK}` } }
  ws.getRow(1).height = 22

  // Categories mirror the organizer market-rate table in the app, so a budget
  // built here maps onto what CueQuote generates.
  const rows = [
    ['Venue', 'Room hire', 1, 'day'], ['Venue', 'Additional breakout rooms', 0, 'day'],
    ['Audio', 'PA system', 1, 'day'], ['Audio', 'Wireless microphones', 4, 'each'],
    ['Audio', 'Mixing console', 1, 'day'], ['Audio', 'Stage monitors', 2, 'each'],
    ['Video', 'Screen or LED wall', 1, 'day'], ['Video', 'Projector and lens', 0, 'day'],
    ['Video', 'Vision switcher', 1, 'day'], ['Video', 'Confidence monitors', 2, 'each'],
    ['Lighting', 'Stage wash', 1, 'day'], ['Lighting', 'Moving heads', 8, 'each'],
    ['Lighting', 'Lighting console', 1, 'day'],
    ['Staging', 'Stage deck', 1, 'set'], ['Staging', 'Lectern', 1, 'each'], ['Staging', 'Backdrop or set', 1, 'set'],
    ['Crew', 'Audio engineer', 1, 'day'], ['Crew', 'Video technician', 1, 'day'],
    ['Crew', 'Lighting operator', 1, 'day'], ['Crew', 'Show caller', 1, 'day'],
    ['Furniture', 'Seating', 0, 'each'], ['Furniture', 'Tables and linen', 0, 'each'],
    ['Registration', 'Registration desk', 1, 'each'], ['Registration', 'Badge printing', 0, 'each'],
    ['Catering', 'Catering per head', 0, 'person'], ['Catering', 'Catering staff', 0, 'day'],
    ['Logistics', 'Delivery and collection', 1, 'trip'], ['Logistics', 'Power or generator', 0, 'day'],
    ['Logistics', 'Parking and access fees', 0, 'item'],
    ['Contingency', 'Contingency at 10%', 1, 'item'],
  ]
  rows.forEach((r) => ws.addRow({ cat: r[0], item: r[1], qty: r[2], unit: r[3] }))

  const first = 2, last = rows.length + 1
  const total = ws.addRow({ item: 'TOTAL' })
  total.font = { bold: true }
  ;['low', 'high', 'quoted', 'actual'].forEach((k) => {
    const col = ws.getColumn(k).letter
    total.getCell(k).value = { formula: `SUM(${col}${first}:${col}${last})` }
  })
  const variance = ws.addRow({ item: 'Variance (actual vs quoted)' })
  variance.font = { bold: true }
  variance.getCell('actual').value = { formula: `${ws.getColumn('actual').letter}${last + 1}-${ws.getColumn('quoted').letter}${last + 1}` }

  ;['low', 'high', 'quoted', 'actual'].forEach((k) => {
    ws.getColumn(k).numFmt = '#,##0.00'
  })
  ws.views = [{ state: 'frozen', ySplit: 1 }]

  const notes = wb.addWorksheet('How to use')
  ;[
    'Event budget template — CueQuote',
    '',
    'Delete rows you do not need. Set Qty to 0 rather than deleting if you might add it back.',
    'Fill Est. low and Est. high first, from experience or market rates. This is the range you take into the room.',
    'Replace estimates with Quoted as real supplier quotes arrive. Keep the estimate — the gap between estimate and quote is the most useful number you will have next time.',
    'Actual is what you were invoiced. Variance shows where the budget moved.',
    'Contingency at 10% is a starting point. Under 5% is optimism; over 20% usually means the scope is not settled yet.',
    '',
    'Totals are formulas — they update as you type. If you insert rows, extend the SUM range.',
    '',
    'cuequote.com',
  ].forEach((line, i) => {
    const r = notes.addRow([line])
    if (i === 0) r.font = { bold: true, size: 14, color: { argb: `FF${DARK}` } }
  })
  notes.getColumn(1).width = 110

  await wb.xlsx.writeFile(`${OUT}/event-budget-template.xlsx`)
}

// ── 4. Corporate event AV checklist ────────────────────────────────────────
function avChecklist() {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'A4', margin: 50 })
    const stream = createWriteStream(`${OUT}/corporate-event-av-checklist.pdf`)
    doc.pipe(stream)
    stream.on('finish', resolve); stream.on('error', reject)

    doc.fillColor(`#${DARK}`).fontSize(22).font('Helvetica-Bold').text('Corporate Event AV Checklist')
    doc.moveDown(0.3)
    doc.fillColor(`#${GREY}`).fontSize(10).font('Helvetica')
       .text('Work down it in order. Anything unticked at the load-in stage becomes a problem during the show.')
    doc.moveDown(1)

    const sections = [
      ['Four weeks out', [
        'Attendee count and seating layout confirmed with the venue',
        'Running order received from the client, with timings',
        'Presentation format confirmed (slides, video, live demo, remote speaker)',
        'Accessibility requirements agreed (captioning, hearing loop, interpretation)',
        'Site visit booked, or venue technical pack received',
        'Rigging points and weight limits confirmed in writing',
        'Power supply and location confirmed',
        'Get-in route measured — lift dimensions, stairs, distance to room',
      ]],
      ['One week out', [
        'Equipment list finalised and reserved against the dates',
        'Crew booked and briefed, with call times issued',
        'Transport booked, load and unload times agreed with the venue',
        'Speaker slides received, or a deadline for them agreed',
        'Rehearsal time confirmed in the schedule',
        'Backup plan agreed for the single point of failure (usually the laptop)',
        'Venue contact and on-site phone numbers circulated to the crew',
      ]],
      ['Load-in', [
        'Access confirmed on arrival, parking cleared',
        'Power tested at the socket before anything is plugged into it',
        'Rigging checked and signed off',
        'Audio system rung out, feedback margin checked at show level',
        'Every microphone tested, batteries fresh, spares labelled and to hand',
        'Screen and projector aligned, resolution matched to the source',
        'Presentation played end to end, including embedded video and audio',
        'Lighting focused, cues recorded',
        'Comms tested between all positions',
        'Cable runs matted or taped where the public walk',
      ]],
      ['Show', [
        'Presenters mic\'d with time to spare, levels checked on each',
        'Spare handheld live and within reach',
        'Recording started, and confirmed to be recording',
        'Someone is watching the room, not only the desk',
      ]],
      ['Strike', [
        'Equipment counted back against the list before leaving',
        'Damage or loss noted and photographed on site',
        'Venue signed off, keys and passes returned',
        'Client debrief booked while the event is still fresh',
      ]],
    ]

    for (const [title, items] of sections) {
      if (doc.y > 690) doc.addPage()
      doc.moveDown(0.5)
      doc.fillColor(`#${GREEN}`).fontSize(13).font('Helvetica-Bold').text(title)
      doc.moveDown(0.35)
      for (const item of items) {
        if (doc.y > 770) doc.addPage()
        const y = doc.y
        doc.lineWidth(0.8).strokeColor('#9CA3AF').rect(52, y + 1.5, 9, 9).stroke()
        doc.fillColor('#1F2937').fontSize(10).font('Helvetica')
           .text(item, 70, y, { width: 470 })
        doc.moveDown(0.35)
      }
    }

    doc.moveDown(1)
    doc.fillColor(`#${GREY}`).fontSize(9)
       .text('Built by CueQuote — AV proposals in minutes. cuequote.com', 50, doc.y, { width: 495 })
    doc.end()
  })
}

await proposalTemplate()
await rfpTemplate()
await budgetTemplate()
await avChecklist()
console.log('built 4 files in', OUT)
